import math

class Solution:
    def isThree(self, n: int) -> bool:
        r = int(math.isqrt(n))
        if r * r != n or r < 2:
            return False
        for d in range(2, int(math.isqrt(r)) + 1):
            if r % d == 0:
                return False
        return True

class Solution {
public:
    bool isThree(int n) {
        int r = round(sqrt(n));
        if (r * r != n || r < 2) return false;
        for (int d = 2; d * d <= r; d++) {
            if (r % d == 0) return false;
        }
        return true;
    }
};

